<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ashley Chen</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;1,400&family=Space+Grotesk:wght@400;500;600&family=JetBrains+Mono:wght@400&display=swap" rel="stylesheet">
<style>
*{box-sizing:border-box;margin:0;padding:0}


:root{
  --bg:#faf8f4;
  --bg-alt:#f3efe8;
  --ink:#1a1917;
  --muted:#7a756b;
  --light:#b5ae9f;
  --warm:#c4794a;
  --cool:#5a6878;
  --serif:'Cormorant Garamond',Georgia,serif;
  --sans:'Space Grotesk',-apple-system,sans-serif;
  --mono:'JetBrains Mono',monospace;
}


html{scroll-behavior:smooth}
body{font-family:var(--sans);background:var(--bg);color:var(--ink);line-height:1.7;-webkit-font-smoothing:antialiased}
a{color:var(--warm);text-decoration:none;transition:opacity .15s}
a:hover{opacity:.7}
::selection{background:var(--warm);color:#fff}


/* ─── NAV ─── */
nav{
  position:fixed;top:0;left:0;bottom:0;z-index:100;
  width:160px;padding:32px 24px;
  display:flex;flex-direction:column;justify-content:space-between;
  background:rgba(250,248,244,.95);backdrop-filter:blur(12px);
  border-right:1px solid #e8e4dc;
}
nav .logo{font-family:var(--serif);font-size:18px;font-weight:600;letter-spacing:-.5px}
nav .nav-links{display:flex;flex-direction:column;gap:20px}
nav .nav-links a{font-size:13px;color:var(--muted);letter-spacing:.3px;transition:color .15s;padding-bottom:2px;border-bottom:1.5px solid transparent;width:fit-content}
nav .nav-links a:hover{color:var(--ink);opacity:1}
nav .nav-links a.active{color:var(--ink);border-bottom-color:var(--warm)}
nav .nav-bottom{font-family:var(--mono);font-size:10px;color:var(--light)}


/* ─── LAYOUT OFFSET ─── */
body{margin-left:160px}


/* ─── HERO ─── */
.hero{
  min-height:100vh;
  display:flex;flex-direction:column;justify-content:center;
  max-width:820px;margin:0 auto;padding:60px 40px 80px;
  position:relative;
}
.hero-label{
  font-family:var(--mono);font-size:11px;letter-spacing:2px;text-transform:uppercase;
  color:var(--light);margin-bottom:32px;
}
.hero h1{
